    user_roles = '{}' OR -- No role restriction
    EXISTS (
      SELECT 1 FROM user_roles ur 
      WHERE ur.user_id = auth.uid() 
      AND ur.role::text = ANY(user_roles)
    )
  )
);

-- Create SMS provider configurations table
