    ORDER BY created_at ASC 
    LIMIT 1;
    
    -- Create subscription if plan exists
    IF trial_plan_id IS NOT NULL THEN
      INSERT INTO public.landlord_subscriptions (
        landlord_id,
        billing_plan_id,
        status,
        trial_start_date,
        trial_end_date,
        sms_credits_balance,
        auto_renewal
      )
      VALUES (
        new_landlord_id,
        trial_plan_id,
        'trial',
        now(),
        now() + interval '30 days',
        100,
        true
      ) ON CONFLICT (landlord_id) DO NOTHING;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;

