-- Fix payments table
DROP POLICY IF EXISTS "Property stakeholders can manage payments" ON public.payments;

CREATE POLICY "Property owners can manage their payments" 
ON public.payments 
FOR ALL 
TO authenticated
USING (
  EXISTS (
    SELECT 1 FROM public.leases l
