ON public.user_roles 
FOR UPDATE 
USING (
  public.can_remove_role(auth.uid(), user_id, role) AND
  public.can_assign_role(auth.uid(), role)
)
WITH CHECK (
  public.can_assign_role(auth.uid(), role) AND
  -- Prevent self-privilege escalation except for Admins
  (auth.uid() != user_id OR public.has_role(auth.uid(), 'Admin'))
);

-- Add role change auditing trigger
CREATE OR REPLACE FUNCTION public.audit_role_changes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
BEGIN
  -- Log role changes for security monitoring
  IF TG_OP = 'INSERT' THEN
    PERFORM public.log_user_audit(
      NEW.user_id, 
      'role_assigned', 
      'user_role', 
      NEW.id::uuid,
      jsonb_build_object(
        'role', NEW.role,
        'assigned_by', auth.uid(),
        'operation', 'INSERT'
      ),
      auth.uid()
    );
    RETURN NEW;
  END IF;
  
  IF TG_OP = 'UPDATE' THEN
    PERFORM public.log_user_audit(
      NEW.user_id, 
      'role_updated', 
      'user_role', 
      NEW.id::uuid,
      jsonb_build_object(
        'old_role', OLD.role,
        'new_role', NEW.role,
        'updated_by', auth.uid(),
        'operation', 'UPDATE'
      ),
      auth.uid()
    );
    RETURN NEW;
  END IF;
  
  IF TG_OP = 'DELETE' THEN
    PERFORM public.log_user_audit(
      OLD.user_id, 
      'role_removed', 
      'user_role', 
      OLD.id::uuid,
      jsonb_build_object(
        'role', OLD.role,
        'removed_by', auth.uid(),
        'operation', 'DELETE'
      ),
      auth.uid()
    );
    RETURN OLD;
  END IF;
  
  RETURN NULL;
END;
$$;

