    SELECT unnest(ARRAY['invoice', 'report', 'letter', 'notice', 'lease', 'receipt']) as doc_type
),
user_roles AS (
    SELECT unnest(ARRAY['Admin', 'Landlord', 'Manager', 'Agent', 'Tenant']) as role,
           unnest(ARRAY[100, 90, 80, 70, 60]) as priority
)
