-- This will help align tenant visibility for historical invoices without affecting landlord reports

UPDATE public.tenants 
SET user_id = auth_users.id
FROM (
  SELECT DISTINCT 
    au.id, 
    au.email
  FROM auth.users au
  WHERE au.email IS NOT NULL
