ON public.knowledge_base_articles
USING (
  is_published = true
  AND (
    ( 'Admin' = ANY (target_user_types)   AND public.has_role(auth.uid(), 'Admin'::public.app_role) )
    OR ( 'Landlord' = ANY (target_user_types) AND public.has_role(auth.uid(), 'Landlord'::public.app_role) )
