    OR ( 'Agent' = ANY (target_user_types)    AND public.has_role(auth.uid(), 'Agent'::public.app_role) )
    OR ( 'Tenant' = ANY (target_user_types)   AND EXISTS (
          SELECT 1 FROM public.tenants WHERE tenants.user_id = auth.uid()
        )
    )
  )
);

