GRANT SELECT ON public.sms_usage_admin_view TO service_role;

-- Create a function to securely insert SMS usage with automatic masking
CREATE OR REPLACE FUNCTION public.insert_sms_usage_secure(
  p_landlord_id UUID,
  p_recipient_phone TEXT,
  p_message_content TEXT,
  p_cost NUMERIC,
  p_status TEXT
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_record_id UUID;
BEGIN
  -- Insert with masked data for security
  INSERT INTO public.sms_usage (
    landlord_id,
    recipient_phone,
    message_content,
    cost,
    status,
    sent_at
  ) VALUES (
    p_landlord_id,
    CONCAT('***', RIGHT(p_recipient_phone, 4)), -- Mask phone number
    CONCAT('[', LENGTH(COALESCE(p_message_content, '')), ' characters]'), -- Mask message content
    p_cost,
    p_status,
    NOW()
  ) RETURNING id INTO v_record_id;
  
  -- Log the action for audit purposes
  INSERT INTO public.user_activity_logs (
    user_id,
    action,
    entity_type,
    entity_id,
    details
  ) VALUES (
    p_landlord_id,
    'sms_sent',
    'sms_usage',
    v_record_id,
    jsonb_build_object(
      'cost', p_cost,
      'status', p_status,
      'message_length', LENGTH(COALESCE(p_message_content, ''))
    )
  );
  
  RETURN v_record_id;
END;
$$;

-- Create audit trigger for SMS usage access
CREATE OR REPLACE FUNCTION public.audit_sms_usage_access()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Log access to SMS data for audit purposes
  INSERT INTO public.user_activity_logs (
    user_id,
    action,
    entity_type,
    entity_id,
    details,
    ip_address
  ) VALUES (
    auth.uid(),
    'sms_usage_accessed',
    'sms_usage',
    NEW.id,
    jsonb_build_object(
      'accessed_at', NOW(),
      'user_role', (
        SELECT role FROM public.user_roles 
        WHERE user_id = auth.uid() 
        LIMIT 1
      )
    ),
    inet_client_addr()
  );
  
  RETURN NEW;
END;
$$;

