RETURNS TEXT
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  decrypted_data TEXT;
  decoded BYTEA;
  iv BYTEA;
  ciphertext BYTEA;
