-- 3. Create encryption/decryption functions
CREATE OR REPLACE FUNCTION public.encrypt_pii(data TEXT, key TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  encrypted_data TEXT;
  iv BYTEA;
BEGIN
  -- Generate a random IV for each encryption
  iv := gen_random_bytes(16);
  
  -- Use pgcrypto for AES-256-CBC encryption
  SELECT encode(
    iv || encrypt_iv(
      data::bytea,
      digest(key, 'sha256'),
      iv,
      'aes-cbc'
    ),
    'base64'
  ) INTO encrypted_data;
  
  RETURN encrypted_data;
EXCEPTION WHEN OTHERS THEN
  -- Log error but don't expose sensitive details
  RAISE EXCEPTION 'Encryption failed';
END;
$$;

CREATE OR REPLACE FUNCTION public.decrypt_pii(encrypted_data TEXT, key TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO 'public'
AS $$
DECLARE
  decrypted_data TEXT;
  decoded BYTEA;
  iv BYTEA;
  ciphertext BYTEA;
BEGIN
  -- Decode the base64 data
  decoded := decode(encrypted_data, 'base64');
  
  -- Extract IV (first 16 bytes) and ciphertext
  iv := substring(decoded from 1 for 16);
  ciphertext := substring(decoded from 17);
  
  -- Use pgcrypto for AES-256-CBC decryption
  SELECT convert_from(
    decrypt_iv(
      ciphertext,
      digest(key, 'sha256'),
      iv,
      'aes-cbc'
    ),
    'utf8'
  ) INTO decrypted_data;
  
  RETURN decrypted_data;
EXCEPTION WHEN OTHERS THEN
  -- Log error but don't expose sensitive details
  RAISE EXCEPTION 'Decryption failed';
END;
$$;

