REVOKE CREATE ON SCHEMA public FROM anon;
REVOKE CREATE ON SCHEMA public FROM authenticated;

-- Revoke all permissions from public and anon on public schema
REVOKE ALL ON SCHEMA public FROM PUBLIC;

