      COALESCE((SELECT SUM(py.amount) FROM public.payments py WHERE py.invoice_id = i.id AND py.status IN ('completed', 'paid', 'success')), 0)
    ) THEN 'paid'
    WHEN i.due_date < CURRENT_DATE THEN 'overdue'
    ELSE i.status
  END as computed_status
