  OR (EXISTS (
    SELECT 1 FROM properties p
    WHERE p.id = expenses.property_id
      AND (
        p.owner_id = auth.uid()
        OR p.manager_id = auth.uid()
        OR (
          p.owner_id = get_sub_user_landlord(auth.uid())
          AND (
            get_landlord_trial_status(get_sub_user_landlord(auth.uid()))
