  'c6305be4-4bf8-4cc4-86a2-0bd578516967', -- invoice_id
  20.00, -- actual paid amount
  'M-Pesa',
  CURRENT_DATE,
  'TLBLU0MEG0', -- mpesa_receipt_number
  'ws_CO_11122025141155063723301507', -- checkout_request_id
  'rent',
