INSERT INTO tenant_credits (
  tenant_id,
  landlord_id,
  amount,
  balance,
  description,
  source_type
) VALUES (
  'f4fafcf8-63f0-4f85-8e98-8988695ef74c', -- tenant_id
  '48a2a4ae-ded3-4c3e-966b-c26711a6d3a9', -- landlord_id (owner_id)
